<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --surface: #121a2f;
      --surface-2: #18233d;
      --border: #2d3a5d;
      --text: #e8eefc;
      --muted: #aab7d8;
      --accent: #7c9cff;
      --accent-strong: #9fb4ff;
      --focus: #ffd166;
      --success: #7dd3a7;
      --error: #ff8fa3;
      --shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 34%),
        linear-gradient(180deg, #070b16 0%, var(--bg) 100%);
      color: var(--text);
    }

    a.skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--focus);
      color: #121212;
      text-decoration: none;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    a.skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #fff;
      outline-offset: 3px;
    }

    main {
      width: min(100%, 920px);
      margin: 0 auto;
      padding: 5rem 1rem 2rem;
    }

    .hero {
      background: linear-gradient(180deg, rgba(24, 35, 61, 0.92), rgba(18, 26, 47, 0.95));
      border: 1px solid var(--border);
      border-radius: 24px;
      padding: 2rem;
      box-shadow: var(--shadow);
      margin-bottom: 1.5rem;
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent-strong);
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 0.8rem;
      font-weight: 700;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.2rem);
      line-height: 1.05;
    }

    .intro {
      margin: 1rem 0 0;
      max-width: 60ch;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1rem;
    }

    .form-field {
      background: rgba(18, 26, 47, 0.88);
      border: 1px solid var(--border);
      border-radius: 22px;
      padding: 1.25rem;
      box-shadow: var(--shadow);
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
      min-inline-size: 0;
    }

    legend {
      display: block;
      width: 100%;
      margin: 0 0 0.75rem;
      font-size: 1.08rem;
      font-weight: 700;
      line-height: 1.4;
    }

    .required-marker {
      color: var(--accent-strong);
      font-weight: 800;
    }

    .help-text,
    .feedback {
      margin: 0 0 1rem;
      color: var(--muted);
      line-height: 1.5;
    }

    .error-text {
      margin: 0 0 1rem;
      color: var(--error);
      font-weight: 600;
    }

    .choice-list {
      display: grid;
      gap: 0.75rem;
    }

    .choice {
      display: grid;
      grid-template-columns: 1.15rem 1fr;
      align-items: start;
      gap: 0.8rem;
      padding: 0.95rem 1rem;
      border-radius: 16px;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(173, 189, 237, 0.14);
      transition: border-color 0.18s ease, background-color 0.18s ease, transform 0.18s ease;
    }

    .choice:hover {
      border-color: rgba(124, 156, 255, 0.45);
      background: rgba(124, 156, 255, 0.08);
      transform: translateY(-1px);
    }

    .choice input {
      margin: 0.2rem 0 0;
      width: 1.05rem;
      height: 1.05rem;
      accent-color: var(--accent);
    }

    .choice label {
      cursor: pointer;
      line-height: 1.45;
      color: var(--text);
    }

    .choice small {
      display: block;
      margin-top: 0.2rem;
      color: var(--muted);
    }

    .actions {
      display: flex;
      justify-content: flex-start;
      gap: 0.75rem;
      margin-top: 0.5rem;
    }

    button {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      background: linear-gradient(180deg, var(--accent-strong), var(--accent));
      color: #0b1020;
      font: inherit;
      font-weight: 800;
      padding: 0.95rem 1.4rem;
      min-height: 3rem;
      cursor: pointer;
      box-shadow: 0 10px 20px rgba(124, 156, 255, 0.24);
    }

    button:hover {
      filter: brightness(1.03);
    }

    button:focus-visible,
    input:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5rem;
      margin-top: 0.5rem;
      color: var(--success);
      font-weight: 600;
    }

    @media (max-width: 640px) {
      main {
        padding-top: 4rem;
      }

      .hero,
      .form-field {
        border-radius: 18px;
        padding: 1rem;
      }

      .actions {
        flex-direction: column;
      }

      button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-2: Canvas;
        --border: CanvasText;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: Highlight;
        --accent-strong: Highlight;
        --focus: Highlight;
        --success: CanvasText;
        --error: CanvasText;
      }

      .hero,
      .form-field,
      .choice,
      button {
        forced-color-adjust: auto;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#quiz">Skip to main content</a>
  <main id="quiz">
    <div id="app"></div>
  </main>

  <script>
    const quizData = [
      {
        id: "q1",
        title: "1. Which of these are programming languages?",
        help: "Select all that apply.",
        options: [
          { id: "q1-a", label: "Python" },
          { id: "q1-b", label: "JavaScript" },
          { id: "q1-c", label: "HTML" },
          { id: "q1-d", label: "Rust" }
        ]
      },
      {
        id: "q2",
        title: "2. Which languages are commonly used for system programming?",
        options: [
          { id: "q2-a", label: "C" },
          { id: "q2-b", label: "C++" },
          { id: "q2-c", label: "Ruby" },
          { id: "q2-d", label: "Rust" }
        ]
      },
      {
        id: "q3",
        title: "3. Which of these are scripting languages?",
        options: [
          { id: "q3-a", label: "Bash" },
          { id: "q3-b", label: "Python" },
          { id: "q3-c", label: "SQL" },
          { id: "q3-d", label: "Fortran" }
        ]
      }
    ];

    function App() {
      return `
        <section class="hero" aria-labelledby="quiz-title">
          <p class="eyebrow">Interactive quiz</p>
          <h1 id="quiz-title">Computer Languages</h1>
          <p class="intro">Pick every answer that fits each question. You can select more than one option per question, then submit when you are done.</p>
        </section>

        <form id="quiz-form" novalidate>
          ${quizData.map(renderQuestion).join("")}

          <div class="form-field">
            <div class="actions">
              <button type="submit">Submit quiz</button>
            </div>
            <p class="status" id="quiz-status" aria-live="polite"></p>
          </div>
        </form>
      `;
    }

    function renderQuestion(question, index) {
      const helpId = question.help ? `${question.id}-help` : "";
      const fieldsetDescribedBy = [helpId].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <fieldset ${fieldsetDescribedBy ? `aria-describedby="${fieldsetDescribedBy}"` : ""}>
            <legend>${question.title}</legend>
            ${question.help ? `<p class="help-text" id="${helpId}">${question.help}</p>` : ""}
            <div class="choice-list">
              ${question.options.map((option) => renderChoice(option, question.id)).join("")}
            </div>
          </fieldset>
        </div>
      `;
    }

    function renderChoice(option, groupName) {
      return `
        <div class="choice">
          <input type="checkbox" id="${option.id}" name="${groupName}" value="${option.label}">
          <label for="${option.id}">${option.label}</label>
        </div>
      `;
    }

    document.getElementById("app").innerHTML = App();

    document.getElementById("quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();
      const status = document.getElementById("quiz-status");
      const checked = Array.from(document.querySelectorAll('input[type="checkbox"]:checked'));

      if (checked.length === 0) {
        status.textContent = "Choose at least one answer before submitting.";
        return;
      }

      const byQuestion = quizData.map((question) => {
        const selections = question.options
          .filter((option) => document.getElementById(option.id).checked)
          .map((option) => option.label);

        return `${question.title.replace(/^\d+\.\s*/, "")} ${selections.length ? selections.join(", ") : "No selection"}`;
      });

      status.textContent = `Submitted. ${checked.length} answers selected. ${byQuestion.join(" | ")}`;
    });
  </script>
</body>
</html>
