       min-inline-size: 0;
     }

     legend {
       display: block;
       width: 100%;
       margin: 0 0 0.75rem;
       font-size: 1.08rem;
       font-weight: 700;
       line-height: 1.4;
     }

     .required-marker {
       color: var(--accent-strong);
       font-weight: 800;
     }

     .help-text,
     .feedback {
       margin: 0 0 1rem;
       color: var(--muted);
       line-height: 1.5;
     }

     .error-text {
       margin: 0 0 1rem;
       color: var(--error);
       font-weight: 600;
     }

     .choice-list {
       display: grid;
       gap: 0.75rem;
     }

     .choice {
       display: grid;
       grid-template-columns: 1.15rem 1fr;
       align-items: start;
       gap: 0.8rem;
       padding: 0.95rem 1rem;
       border-radius: 16px;
       background: rgba(255, 255, 255, 0.03);
       border: 1px solid rgba(173, 189, 237, 0.14);
       transition: border-color 0.18s ease, background-color 0.18s ease, transform 0.18s ease;
     }

     .choice:hover {
       border-color: rgba(124, 156, 255, 0.45);
       background: rgba(124, 156, 255, 0.08);
       transform: translateY(-1px);
     }

     .choice input {
       margin: 0.2rem 0 0;
       width: 1.05rem;
       height: 1.05rem;
       accent-color: var(--accent);
     }

     .choice label {
       cursor: pointer;
       line-height: 1.45;
       color: var(--text);
     }

     .choice small {
       display: block;
       margin-top: 0.2rem;
       color: var(--muted);
     }

     .actions {
       display: flex;
       justify-content: flex-start;
       gap: 0.75rem;
       margin-top: 0.5rem;
     }

     button {
       appearance: none;
       border: 1px solid transparent;
       border-radius: 999px;
       background: linear-gradient(180deg, var(--accent-strong), var(--accent));
       color: #0b1020;
       font: inherit;
       font-weight: 800;
       padding: 0.95rem 1.4rem;
       min-height: 3rem;
       cursor: pointer;
       box-shadow: 0 10px 20px rgba(124, 156, 255, 0.24);
     }

     button:hover {
       filter: brightness(1.03);
     }

     button:focus-visible,
     input:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .status {
       min-height: 1.5rem;
       margin-top: 0.5rem;
       color: var(--success);
       font-weight: 600;
     }

     @media (max-width: 640px) {
       main {
         padding-top: 4rem;
       }

       .hero,
       .form-field {
         border-radius: 18px;
         padding: 1rem;
       }

       .actions {
         flex-direction: column;
       }

       button {
         width: 100%;
       }
     }

     @media (forced-colors: active) {
       :root {
         --bg: Canvas;
         --surface: Canvas;
         --surface-2: Canvas;
         --border: CanvasText;
         --text: CanvasText;
         --muted: CanvasText;
         --accent: Highlight;
         --accent-strong: Highlight;
         --focus: Highlight;
         --success: CanvasText;
         --error: CanvasText;
       }

       .hero,
       .form-field,
       .choice,
       button {
         forced-color-adjust: auto;
       }
