 <body>
   <a class="skip-link" href="#quiz">Skip to main content</a>
   <main id="quiz">
     <div id="app"></div>
   </main>

   <script>
     const quizData = [
       {
         id: "q1",
         title: "1. Which of these are programming languages?",
         help: "Select all that apply.",
         options: [
           { id: "q1-a", label: "Python" },
           { id: "q1-b", label: "JavaScript" },
           { id: "q1-c", label: "HTML" },
           { id: "q1-d", label: "Rust" }
         ]
       },
       {
         id: "q2",
         title: "2. Which languages are commonly used for system programming?",
         options: [
           { id: "q2-a", label: "C" },
           { id: "q2-b", label: "C++" },
           { id: "q2-c", label: "Ruby" },
           { id: "q2-d", label: "Rust" }
         ]
       },
       {
         id: "q3",
         title: "3. Which of these are scripting languages?",
         options: [
           { id: "q3-a", label: "Bash" },
           { id: "q3-b", label: "Python" },
           { id: "q3-c", label: "SQL" },
           { id: "q3-d", label: "Fortran" }
         ]
       }
     ];

     function App() {
       return `
         <section class="hero" aria-labelledby="quiz-title">
           <p class="eyebrow">Interactive quiz</p>
           <h1 id="quiz-title">Computer Languages</h1>
           <p class="intro">Pick every answer that fits each question. You can select more than one option per question, then submit when you are done.</p>
         </section>

         <form id="quiz-form" novalidate>
           ${quizData.map(renderQuestion).join("")}

           <div class="form-field">
             <div class="actions">
               <button type="submit">Submit quiz</button>
             </div>
             <p class="status" id="quiz-status" aria-live="polite"></p>
           </div>
         </form>
       `;
     }

     function renderQuestion(question, index) {
       const helpId = question.help ? `${question.id}-help` : "";
       const fieldsetDescribedBy = [helpId].filter(Boolean).join(" ");

       return `
         <div class="form-field">
           <fieldset ${fieldsetDescribedBy ? `aria-describedby="${fieldsetDescribedBy}"` : ""}>
             <legend>${question.title}</legend>
             ${question.help ? `<p class="help-text" id="${helpId}">${question.help}</p>` : ""}
             <div class="choice-list">
               ${question.options.map((option) => renderChoice(option, question.id)).join("")}
             </div>
           </fieldset>
         </div>
       `;
     }

     function renderChoice(option, groupName) {
       return `
         <div class="choice">
           <input type="checkbox" id="${option.id}" name="${groupName}" value="${option.label}">
           <label for="${option.id}">${option.label}</label>
         </div>
       `;
     }

     document.getElementById("app").innerHTML = App();

     document.getElementById("quiz-form").addEventListener("submit", (event) => {
       event.preventDefault();
       const status = document.getElementById("quiz-status");
       const checked = Array.from(document.querySelectorAll('input[type="checkbox"]:checked'));

       if (checked.length === 0) {
         status.textContent = "Choose at least one answer before submitting.";
         return;
       }

       const byQuestion = quizData.map((question) => {
         const selections = question.options
           .filter((option) => document.getElementById(option.id).checked)
           .map((option) => option.label);

         return `${question.title.replace(/^\d+\.\s*/, "")} ${selections.length ? selections.join(", ") : "No selection"}`;
       });

       status.textContent = `Submitted. ${checked.length} answers selected. ${byQuestion.join(" | ")}`;
     });
   </script>
 </body>
 </html>

