 <!doctype html>
 <html lang="en">
 <head>
   <meta charset="utf-8">
   <meta name="viewport" content="width=device-width, initial-scale=1">
   <title>Computer Languages Quiz</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
