       transform: translateY(-180%);
       transition: transform 0.2s ease;
       z-index: 10;
     }

     a.skip-link:focus {
       transform: translateY(0);
       outline: 3px solid #fff;
       outline-offset: 3px;
     }

     main {
       width: min(100%, 920px);
       margin: 0 auto;
       padding: 5rem 1rem 2rem;
     }

     .hero {
       background: linear-gradient(180deg, rgba(24, 35, 61, 0.92), rgba(18, 26, 47, 0.95));
       border: 1px solid var(--border);
       border-radius: 24px;
       padding: 2rem;
       box-shadow: var(--shadow);
       margin-bottom: 1.5rem;
     }

     .eyebrow {
       margin: 0 0 0.5rem;
       color: var(--accent-strong);
       text-transform: uppercase;
       letter-spacing: 0.12em;
       font-size: 0.8rem;
       font-weight: 700;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 3.2rem);
       line-height: 1.05;
     }

     .intro {
       margin: 1rem 0 0;
       max-width: 60ch;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 1rem;
     }

     .form-field {
       background: rgba(18, 26, 47, 0.88);
       border: 1px solid var(--border);
       border-radius: 22px;
       padding: 1.25rem;
       box-shadow: var(--shadow);
     }

     fieldset {
       margin: 0;
       padding: 0;
       border: 0;
       min-inline-size: 0;
     }

     legend {
       display: block;
       width: 100%;
       margin: 0 0 0.75rem;
       font-size: 1.08rem;
       font-weight: 700;
       line-height: 1.4;
     }

     .required-marker {
       color: var(--accent-strong);
       font-weight: 800;
     }

     .help-text,
     .feedback {
       margin: 0 0 1rem;
       color: var(--muted);
       line-height: 1.5;
     }

     .error-text {
       margin: 0 0 1rem;
       color: var(--error);
       font-weight: 600;
     }

     .choice-list {
       display: grid;
